fn bitwise_xor(a: Vec<u8>, b: Vec<u8>) -> Vec<u8> {
    // Since a and b have equal lengths and are non-empty,
    // zip safely pairs corresponding elements.
    a.iter()
     .zip(b.iter())
     .map(|(&x, &y)| x ^ y)
     .collect()
}